// ---- story (chapter Ch9, ch9 agent 2026-10-07; Sapphire data/maps/MossdeepCity_StevensHouse/scripts.inc; generators must
// keep everything from this line on; entries above marked "// story:"). Scripts 6-11, text lines 5-15 of the text file.
// Room tiles = Sapphire tiles + (1, 1). People (data/story/ch9.json, uid = Sapphire local id; Steven is the zone's first
// NPC, index 0): Steven 1 (hidden by FLAG_HIDE_STEVEN_STEVENS_HOUSE), the Poké Ball with Beldum 2 (FLAG_HIDE_BELDUM_BALL_
// STEVENS_HOUSE), the HM ball 3 (FLAG_ITEM_MOSSDEEP_STEVENS_HOUSE_HM08: shown by the Hall of Fame when HM08 was never
// received), the sign on the table at (6,4) for Steven's letter (Sapphire: an invisible object hidden by FLAG_HIDE_
// STEVENS_LETTER). Map scripts: 0679 (zone init = script 8, OnFrame VAR_STEVENS_HOUSE_STATE 0 = script 7).
// Beldum's ball and the letter are chapter Ch13's beats (post-game): scripts 10 and 11 are Sapphire's, written here as the
// fallback; Ch13 may replace them with scenes/MossdeepCity_StevensHouse_Ch13.inc (labels Ch13_SH_BeldumBall,
// Ch13_SH_Letter), which is picked up when it exists. HM08 Dive is Black 2's HM06 (Sapphire's HM08: Black 2 has 6 HMs).
// Not here: Sapphire's OnLoad hides the letter's table tile until the game is cleared (setmetatile TableEdge).
#include "scenes/ch9_lib.inc"
#define T_UnderwaterCavern 5
#define T_YouveEarnedHMDive 6
#define T_ExplainDive 7
#define T_TakeBall 8
#define T_ObtainedBeldum 9
#define T_NoSpace 10
#define T_LeftBall 11
#define T_LetterWithDive 12
#define T_Letter 13
#define T_Nickname 14
#define T_BagFull 15
#define SH_STEVEN 1
#define SH_BELDUM_BALL 2
#define SH_DIVE_BALL 3
#define SH_STEVEN_INDEX 0               // Steven's position in the zone's NPC list (ObjInitNPCGPos)

SH_Steven:                              // MossdeepCity_StevensHouse_EventScript_Steven
    h_msgbox_npc T_UnderwaterCavern     // Steven: Apparently, there's an underwater cavern between Mossdeep and Sootopolis. ...

SH_StevenGivesDive:                     // MossdeepCity_StevensHouse_EventScript_StevenGivesDive (OnFrame VAR_STEVENS_HOUSE_STATE 0)
    h_lock
#ifdef HOENN_EMERALD
    // EMERALD (emerald_ch9_mirage 2026-10-12): pokeemerald's numbering is 0 = the Space Center is not done, 1 = the Dive is due (the Space Center's
    // end sets it), 2 = given; the OnFrame (0679) runs this at 1. A state that was set to 1 after the Dive (the Hall of Fame's shared line) is just
    // finished
    h_goto_if_unset FLAG_RECEIVED_HM08, L_SH_EmGiveDive
    h_setvar VAR_STEVENS_HOUSE_STATE, 2
    h_release
L_SH_EmGiveDive:
#endif
    h_applymovement SH_STEVEN, Common_Movement_WalkInPlaceFastestLeft
    h_waitmovement
    h_applymovement SH_STEVEN, Common_Movement_ExclamationMark      // (playse SE_PIN: the "!" plays its own sound)
    h_waitmovement
    h_applymovement SH_STEVEN, Common_Movement_Delay48
    h_waitmovement
    h_applymovement SH_STEVEN, Mv_SH_StevenApproachPlayer
    h_waitmovement
    h_buffer_player
    h_msgbox_actor T_YouveEarnedHMDive, SH_STEVEN   // Steven: <player>? Yes, this is my place. ... Oh, here, you should take this HM. ...
    h_closemessage                      // (Black 2: the item script opens its own window)
    h_giveitem ITEM_HM06                // giveitem ITEM_HM08_DIVE (Black 2's HM06 is Dive)
    h_setflag FLAG_RECEIVED_HM08
    h_setflag FLAG_OMIT_DIVE_FROM_STEVEN_LETTER
    h_msgbox_actor T_ExplainDive, SH_STEVEN         // Steven: While you're using Surf, you should notice dark patches of water. ...
    h_closemessage
    VMSleep 10                          // delay 20
    h_applymovement SH_STEVEN, Mv_SH_StevenReturn
    h_waitmovement
#ifdef HOENN_EMERALD
    h_setflag FLAG_HIDE_MOSSDEEP_CITY_SCOTT                        // pokeemerald: Scott in town is gone for good, and the Aqua grunt
    h_setflag FLAG_HIDE_SEAFLOOR_CAVERN_ENTRANCE_AQUA_GRUNT        // at the Seafloor Cavern (Dive leads there)
    h_setvar VAR_STEVENS_HOUSE_STATE, 2
#else
    h_setvar VAR_STEVENS_HOUSE_STATE, 1
#endif
    h_release

SH_Init:                                // MossdeepCity_StevensHouse_OnTransition
#ifdef HOENN_EMERALD
    h_goto_if_ne VAR_STEVENS_HOUSE_STATE, 2, L_SH_InitDone
    ObjInitNPCGPos SH_STEVEN_INDEX, 0, 7, 0, 6      // pokeemerald's ..._EventScript_SetStevenPos: Steven at (6,5), FACE_UP
#else
    h_goto_if_ne VAR_STEVENS_HOUSE_STATE, 1, L_SH_InitDone
    ObjInitNPCGPos SH_STEVEN_INDEX, 2, 7, 0, 6      // MossdeepCity_StevensHouse_EventScript_SetStevenPos: Steven at (6,5), FACE_LEFT
#endif
L_SH_InitDone:
    VMHalt

SH_DiveBall:                            // MossdeepCity_StevensHouse_EventScript_DiveItemBall (finditem ITEM_HM08_DIVE)
    h_lock
    h_giveitem ITEM_HM06
    h_goto_if_eq HLIB_RESULT, 0, L_SH_BagFull
    h_removeobject SH_DIVE_BALL, FLAG_ITEM_MOSSDEEP_STEVENS_HOUSE_HM08
    h_setflag FLAG_RECEIVED_HM08
    h_release
L_SH_BagFull:                           // Common_EventScript_ShowBagIsFull
    h_bag_is_full T_BagFull
    h_release

#if __has_include("scenes/MossdeepCity_StevensHouse_Ch13.inc")
#include "scenes/MossdeepCity_StevensHouse_Ch13.inc"
#else
SH_BeldumBall_Fallback:
Ch13_SH_BeldumBall:                     // MossdeepCity_StevensHouse_EventScript_BeldumPokeball (lockall)
    h_lock
    h_buffer_player
    h_yesno T_TakeBall, C9_A            // <player> checked the Poké Ball. It contained the Pokémon Beldum. Take the Poké Ball?
    h_goto_if_no C9_A, L_SH_LeaveBeldum
    h_getpartysize C9_B
    h_goto_if_eq C9_B, 6, L_SH_NoSpace
    h_removeobject SH_BELDUM_BALL, FLAG_HIDE_BELDUM_BALL_STEVENS_HOUSE
    h_closemessage
    h_playfanfare MUS_OBTAIN_ITEM
    h_buffer_player
    h_msgbox_info T_ObtainedBeldum      // <player> obtained a Beldum.
    h_waitfanfare
    PokePartyAdd C9_C, SPECIES_BELDUM, 0, 5     // givemon SPECIES_BELDUM, 5, ITEM_NONE
    h_closemessage
    WordSetPokeSpecies 2, SPECIES_BELDUM    // bufferspeciesname 1
    h_yesno T_Nickname, C9_A            // Want to give a nickname to the Beldum you received?
    h_goto_if_no C9_A, L_SH_BeldumDone
    h_name_received_mon C9_B            // (the party size before = the new one's slot)
L_SH_BeldumDone:
    h_setflag FLAG_HIDE_BELDUM_BALL_STEVENS_HOUSE
    h_setflag FLAG_RECEIVED_BELDUM
    h_release
L_SH_NoSpace:                           // MossdeepCity_StevensHouse_EventScript_GiveBeldum
    h_msgbox T_NoSpace                  // There is no space for another Pokémon.
    h_release
L_SH_LeaveBeldum:                       // MossdeepCity_StevensHouse_EventScript_LeaveBeldum
    h_buffer_player
    h_msgbox T_LeftBall                 // <player> left the Poké Ball where it was.
    h_release

Ch13_SH_Letter:                         // MossdeepCity_StevensHouse_EventScript_Letter (lockall; the object exists once the game is cleared)
    h_lock
    h_goto_if_set FLAG_HIDE_STEVENS_LETTER, L_SH_NoLetter
    h_buffer_player
    h_goto_if_set FLAG_OMIT_DIVE_FROM_STEVEN_LETTER, L_SH_LetterWithoutDive
    h_msgbox_info T_LetterWithDive      // It's a letter. ... If you'd like, you should also take the HM Dive. ...
    h_closemessage
    h_release
L_SH_LetterWithoutDive:
    h_msgbox_info T_Letter              // It's a letter. ... I have a favor to ask of you. ...
    h_closemessage
    h_release
L_SH_NoLetter:
    h_release
#endif

    .balign 4, 0
Mv_SH_StevenApproachPlayer:             // MossdeepCity_StevensHouse_Movement_StevenApproachPlayer
    walk_left 6
    walk_in_place_fastest_down
    step_end
Mv_SH_StevenReturn:                     // MossdeepCity_StevensHouse_Movement_StevenReturn
    walk_up
    walk_right 3
    walk_in_place_fastest_up
    step_end
#include "common/movement.inc"
